# Validate the submitted transformation against both demos, including exact altered coordinates.
# For input interior dimensions, apply 2 to boundary layer, 5 to next layer, retain zeros deeper.
def transform(h,w,top,left,bottom,right):
 out=[[0]*w for _ in range(h)]
 for c in range(left,right+1): out[top][c]=out[bottom][c]=5
 for r in range(top,bottom+1): out[r][left]=out[r][right]=5
 for r in range(top+1,bottom):
  for c in range(left+1,right):
   d=min(r-(top+1),c-(left+1),(bottom-1)-r,(right-1)-c)
   if d<2: out[r][c]=2 if d==0 else 5
 return out
for bounds in [(1,1,9,9),(0,0,5,5)]:
 print(bounds, transform(13 if bounds[0] else 6,13 if bounds[0] else 6,*bounds))

